	@TempDir
	Path directory;
	private SailRepository repository;
	private RepositoryConnection connection;

	private void open(Backend backend) {
		Sail base = switch (backend) {
		case MEMORY -> new MemoryStore();
		case NATIVE -> new NativeStore(directory.toFile());
		case LMDB -> new LmdbStore(directory.toFile());
		};
		repository = new SailRepository(new RdfParserSail(base));
		repository.init();
		connection = repository.getConnection();
	}

	@AfterEach
	void close() {
		try {
			if (connection != null) {
				connection.close();
			}
		} finally {
			if (repository != null) {
				repository.shutDown();
			}
		}
	}

	private List<BindingSet> select(String sparql, String document) {
		var query = connection.prepareTupleQuery(QueryLanguage.SPARQL, P + sparql);
		if (document != null) {
			query.setBinding("doc", VF.createLiteral(document));
		}
		List<BindingSet> rows = new ArrayList<>();
		try (var result = query.evaluate()) {
			while (result.hasNext()) {
				rows.add(result.next());
			}
		}
		return rows;
	}

	private void update(String sparql, String document) {
		var update = connection.prepareUpdate(QueryLanguage.SPARQL, P + sparql);
		update.setBinding("doc", VF.createLiteral(document));
		update.execute();
	}

